'use strict';
let deckDrag=null;
function selectedDeck(){return state.decks.find(d=>d.id===currentDeck);}
function deckOptions(values,placeholder){return `<option value="">${placeholder}</option>`+Object.entries(values).map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('');}
function initDeckWorkbench(){const panel=$('#deckWorkbench');if(panel.dataset.ready)return;panel.dataset.ready='true';$('#deckFilterHost').innerHTML=`<input id="dfSearch" type="search" placeholder="Buscar una carta o su efecto…" aria-label="Buscar cartas para el mazo"><div class="deck-filter-row"><select id="dfSet" aria-label="Expansión del mazo">${deckOptions(Object.fromEntries([...SETS,...STARTERS].map(s=>[s.id,s.name])),'Todas las expansiones')}</select><select id="dfRarity" aria-label="Rareza para el mazo">${deckOptions(names,'Todas las rarezas')}</select></div><details class="advanced-filters"><summary>Filtros de cartas</summary><div class="deck-filter-row"><label>Categoría<select id="dfCategory">${deckOptions({monster:'Monstruos',spell:'Mágicas',trap:'Trampas'},'Todas')}</select></label><label>Tipo de carta<select id="dfType">${deckOptions(types,'Todos')}</select></label><label>Atributo<select id="dfAttribute">${deckOptions(attrs,'Todos')}</select></label><label>Tipo de monstruo<select id="dfRace">${deckOptions(Object.fromEntries(Object.entries(races).filter(([k])=>cards.some(c=>c.type.includes('Monster')&&c.race===k))),'Todos')}</select></label><label>Clase mágica / trampa<select id="dfProperty">${deckOptions(Object.fromEntries(Object.entries(races).filter(([k])=>cards.some(c=>!c.type.includes('Monster')&&c.race===k))),'Todas')}</select></label></div><div class="filter-ranges">${[['atk','ATK'],['def','DEF'],['level','Nivel']].map(([k,n])=>`<fieldset><legend>${n}</legend><div><label>Desde<input id="df${k}Min" type="number" min="0" aria-label="${n} mínimo para mazo"></label><label>Hasta<input id="df${k}Max" type="number" min="0" aria-label="${n} máximo para mazo"></label></div></fieldset>`).join('')}</div></details><div class="deck-filter-row"><label>Orden<select id="dfSort">${deckOptions({name:'Nombre',atk:'Ataque',def:'Defensa',level:'Nivel',rarity:'Rareza',copies:'Copias'},'Número de carta')}</select></label><label>Dirección<select id="dfDirection"><option value="asc">Menor a mayor / A–Z</option><option value="desc">Mayor a menor / Z–A</option></select></label></div><div class="deck-filter-row"><label><input id="dfAvailable" type="checkbox"> Solo copias disponibles</label><button id="dfReset" class="quiet">Limpiar filtros</button></div><p id="dfError" role="alert"></p>`;$('#deckFilterHost').addEventListener('input',renderDeckLibrary);$('#deckFilterHost').addEventListener('change',renderDeckLibrary);$('#dfReset').onclick=()=>{$('#deckFilterHost').querySelectorAll('input,select').forEach(el=>{if(el.type==='checkbox')el.checked=false;else el.value=el.id==='dfDirection'?'asc':'';});renderDeckLibrary();};$('#deckSwitch').onchange=e=>{currentDeck=e.target.value;renderDecks();};$('#deckName').onchange=e=>{const d=selectedDeck();if(!d)return;d.name=e.target.value.trim()||'Mi mazo';save();renderDecks();};$('#deleteDeckVisual').onclick=()=>{const d=selectedDeck();if(!d)return;modal('<h2>¿Eliminar este mazo?</h2><p>Las cartas seguirán en tu colección.</p><button id="confirmDelete">Eliminar mazo</button>');$('#confirmDelete').onclick=()=>{state.decks=state.decks.filter(x=>x.id!==d.id);currentDeck=null;save();renderDecks();$('#modal').close();};};}
function renderVisualDecks(){initDeckWorkbench();if(!selectedDeck())currentDeck=state.decks[0]?.id||null;const d=selectedDeck();$('#deckSwitch').innerHTML=state.decks.length?state.decks.map(x=>`<option value="${esc(x.id)}" ${x.id===currentDeck?'selected':''}>${esc(x.name)}</option>`).join(''):'<option value="">Todavía no hay mazos</option>';$('#deckName').disabled=!d;$('#deckName').value=d?.name||'';$('#deleteDeckVisual').disabled=!d;const count=d?deckCounts(d):{main:0,extra:0};$('#mainDeckCount').textContent=count.main+' / 60';$('#extraDeckCount').textContent=count.extra+' / 15';$('#deckBuildStatus').textContent=!d?'Creá un mazo para empezar a agregar cartas.':count.main<40?`Borrador · faltan ${40-count.main} cartas principales para llegar a 40`:'Tamaño válido · guardado automático';$('#deckComposition').textContent=d?['Monstruos','Mágicas','Trampas'].map((label,i)=>label+': '+Object.entries(d.cards).reduce((n,[id,copies])=>{const c=byId.get(id);return n+((i===0?c.type.includes('Monster')&&c.type!=='Fusion Monster':i===1?c.type==='Spell Card':c.type==='Trap Card')?copies:0);},0)).join(' · '):'';for(const area of ['main','extra']){const entries=d?Object.entries(d.cards).filter(([id])=>(byId.get(id).type==='Fusion Monster')===(area==='extra')):[];$('#'+area+'DeckGrid').innerHTML=entries.length?entries.flatMap(([id,n])=>Array.from({length:n},(_,i)=>deckCard(byId.get(id),true,i))).join(''):`<div class="drop-placeholder"><span>＋</span>${area==='extra'?'Arrastrá tus monstruos de fusión':'Arrastrá tus cartas a esta zona'}<small>${area==='extra'?'Hasta 15 cartas':'Monstruos, mágicas y trampas · 40–60 cartas'}</small></div>`;}renderDeckLibrary();}
function deckCard(c,inside=false,index=0){const d=selectedDeck(),used=d?.cards[c.id]||0,owned=state.owned[c.id]||0,free=Math.max(0,Math.min(3,owned)-used),enabled=inside||!!d&&free>0;return `<article class="deck-card ${rarityClass(c)} ${!inside&&!free?'used-up':''}" draggable="${enabled}" data-drag-id="${c.id}" data-drag-origin="${inside?'deck':'library'}"><button class="deck-card-image" data-card="${c.id}" aria-label="Ver ${esc(c.name_es)}"><img draggable="false" src="${esc(image(c))}" alt="${esc(c.name_en)}" loading="lazy"></button><span class="deck-card-badge">${inside?(index+1)+' / '+used:used+' / '+Math.min(owned,3)+' en mazo'}</span><span class="deck-card-title">${esc(c.name_es)}</span><small class="deck-card-rarity">${names[c.rarity]}</small>${inside?`<button class="deck-remove" data-minus="${c.id}" aria-label="Quitar ${esc(c.name_es)} del mazo">− Quitar</button>`:`<span class="deck-stock">Tenés ${owned} · disponibles ${free}</span><button class="deck-add-button" data-plus="${c.id}" ${enabled?'':'disabled'} aria-label="Agregar ${esc(c.name_es)} al mazo">＋ Agregar</button>`}</article>`;}
function renderDeckLibrary(){if(!$('#dfSearch'))return;const array=id=>$(id).value?[$(id).value]:[];const f={search:$('#dfSearch').value,searchEffect:true,onlyOwned:true,set:$('#dfSet').value,rarity:$('#dfRarity').value,categories:array('#dfCategory'),types:array('#dfType'),attributes:array('#dfAttribute'),races:array('#dfRace'),properties:array('#dfProperty'),sort:$('#dfSort').value||'code',direction:$('#dfDirection').value};for(const k of ['atk','def','level'])for(const edge of ['Min','Max'])f[k+edge]=$('#df'+k+edge).value;let result=window.CollectionQuery(cards,state.owned,f);const d=selectedDeck();if($('#dfAvailable').checked)result.cards=result.cards.filter(c=>Math.min(3,state.owned[c.id]||0)>(d?.cards[c.id]||0));$('#dfError').textContent=result.error;$('#deckLibraryCount').textContent=result.cards.length+' cartas de tu colección';const grid=$('#deckLibraryGrid'),position=grid.scrollTop;grid.innerHTML=result.cards.length?result.cards.map(c=>deckCard(filteredPrint(c,$('#dfSet').value))).join(''):'<p class="deck-empty">No hay cartas que coincidan. Cambiá los filtros o abrí sobres para ampliar tu colección.</p>';grid.scrollTop=position;}
function performDeckDrop(payload,zone){if(!payload||payload.deckId!==currentDeck||!byId.has(String(payload.id))||!selectedDeck())return false;const c=byId.get(String(payload.id));if(payload.origin==='deck'&&zone==='library'){changeDeck(payload.id,-1);return true;}if(payload.origin!=='library'||zone==='library')return false;if(zone==='extra'&&c.type!=='Fusion Monster'||zone==='main'&&c.type==='Fusion Monster'){toast(c.type==='Fusion Monster'?'Las fusiones van en el mazo de fusiones.':'Esta carta va en el mazo principal.');return false;}const before=selectedDeck().cards[payload.id]||0;changeDeck(payload.id,1);return (selectedDeck().cards[payload.id]||0)>before;}
function clearDeckDrag(){document.querySelectorAll('.drop-hover,.dragging').forEach(el=>el.classList.remove('drop-hover','dragging'));deckDrag=null;}
$('#mazos').addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-id]');if(!card||card.draggable!==true){e.preventDefault();return;}deckDrag={id:card.dataset.dragId,origin:card.dataset.dragOrigin,deckId:currentDeck};e.dataTransfer.setData('text/plain',card.dataset.dragId);e.dataTransfer.effectAllowed='copyMove';card.classList.add('dragging');});
$('#mazos').addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-zone]');if(!deckDrag||!zone)return;e.preventDefault();e.dataTransfer.dropEffect=deckDrag.origin==='deck'?'move':'copy';document.querySelectorAll('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));zone.classList.add('drop-hover');});
$('#mazos').addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-zone]');if(!zone||!deckDrag)return;e.preventDefault();const payload=deckDrag;clearDeckDrag();performDeckDrop(payload,zone.dataset.dropZone);});
$('#mazos').addEventListener('dragend',clearDeckDrag);
